mapper.select:
SELECT dp.*, dc.category_name, u.real_name AS applicant_name FROM device_purchase dp LEFT JOIN device_category dc ON dp.category_id = dc.id LEFT JOIN `user` u ON dp.applicant_id = u.id
AND dp.status = #{status}
ORDER BY dp.create_time DESC

mapper.update:
UPDATE device_purchase
device_name = #{deviceName}, model = #{model}, category_id = #{categoryId}, quantity = #{quantity}, unit_price = #{unitPrice}, supplier = #{supplier}, purpose = #{purpose}, status = #{status}, audit_user_id = #{auditUserId}, audit_time = #{auditTime},
WHERE id = #{id}
